fn min(a: &Vec<i32>, n: usize) -> i32 {
    // Precondition: n > 0 and n <= a.len()
    let mut current_min = a[0];
    for i in 1..n {
        if a[i] < current_min {
            current_min = a[i];
        }
    }
    current_min
}

